/**
 * The live preview page module, bound to every /themes/<id>/preview by its
 * asset key (js/pages/themes/[id]/preview/index.js). The viewport pills stamp
 * the stage's data-viewport and mark the pressed one; the stylesheet sizes the
 * frame from that stamp. No framework imports: the pills are libs/pills.js.
 */
import { bindPills } from '../../../../libs/pills.js';

export default async () => {
  const $stage = document.querySelector('[data-explorer-stage]');

  const pressViewport = bindPills(document.querySelector('[data-explorer-viewports]'), (viewport) => setViewport(viewport));
  const setViewport = (viewport) => {
    $stage.dataset.viewport = viewport;
    pressViewport(viewport);
  };
};
